import { useEffect, useState, Fragment } from "react";
import {
	ConfigProvider,
	Panel,
	PanelHeader,
	CardGrid,
	Card,
	Slider,
	FormItem,
	HorizontalScroll,
	Input,
	FormStatus,
	Footer,
	SimpleCell,
	Link,
	Avatar,
} from "@vkontakte/vkui";
import {
	Icon28ChevronBack,
	Icon28CoinsOutline,
	Icon24DoneOutline,
	Icon28BombOutline,
	Icon28RemoveCircleOutline,
	Icon28AddCircleOutline,
} from "@vkontakte/icons";
const Buttons = ({ props, item }) => {
	var color = [
		"#8bc34a",
		"#2196f3",
		"#f44336",
		"var(--color_background_buttons_dark)",
	];
	return (
		<Fragment>
			<div
				className="button"
				onClick={
					props.gameData.line === item
						? (v) => props.open(Number(v.currentTarget.dataset.itemid))
						: null
				}
				data-itemid={0}
				style={{
					width: "20%",
					height: 45,
					display: "flex",
					marginLeft: 3,
					marginTop: 3,
					alignSelf: "flex-start",
					alignItems: "center",
					justifyContent: "center",
					background:
						props.gameData.state === 3
							? props.gameData.open[item] === 0
								? color[0]
								: props.gameData.fields[item][0] === true
								? color[2]
								: color[1]
							: props.gameData.open[item] === 0
							? color[0]
							: props.gameData.open[item] === true
							? color[2]
							: color[3],
					borderRadius: 12,
					transition: "transform .2s cubic-bezier(.175,.885,.32,1.275)",
					color: "white",
					...(props.gameData.state === 3
						? props.gameData.loseItem === 0 &&
						  props.gameData.open[item] === true
							? { boxShadow: "0 0 10px 0 #f44336" }
							: null
						: null),
				}}
			>
				{props.gameData.state === 3 ? (
					props.gameData.open[item] === 0 ? (
						<Icon28CoinsOutline />
					) : props.gameData.fields[item][0] === true ? (
						<Icon28BombOutline />
					) : (
						<Icon28CoinsOutline />
					)
				) : props.gameData.open[item] === 0 ? (
					<Icon28CoinsOutline />
				) : props.gameData.open[item] === true ? (
					<Icon28BombOutline />
				) : null}
			</div>
			<div
				className="button"
				onClick={
