														fontSize: 20,
														padding: 5,
														display: "flex",
														alignItems: "center",
														justifyContent: "center",
													}}
												>
													x{user.coef}
												</div>
											}
											subtitle={
												<div
													style={{
														color:
															user.win === 1
																? "#1AB095"
																: user.win === 2
																? "#E74C3C"
																: "",
													}}
												>
													<div>
														{user.win === 1 ? "+" : user.win === 2 ? "-" : ""}
														{props.number_format(user.bet)}
														<Icon28CoinsOutline
															width={16}
															height={16}
															className="vkIcon"
														/>
													</div>
												</div>
											}
										>
											<div
												style={{
													color: user.color ? user.color : "white",
												}}
											>
												{user.nick ? user.nick : "@" + user.user}
											</div>
										</SimpleCell>
									);
								})}
							</Fragment>
						)}
						{props.gameData.state >= 2 && (
							<Fragment>
								<div
									style={{
										marginLeft: 20,
										marginRight: 20,
										marginTop: 10,
									}}
								>
									<div
										style={{
											width: "100%",
											borderRadius: "var(--radius_button)",
											background: "var(--color_background_buttons)",
											color: "white",
											overflow: "hidden",
										}}
									>
										<div
											style={{
												padding: "2px 4px 4px",
											}}
										>
											{props.gameData.open.map((x, i) => {
												return (
													<div
														style={{
															opacity: i === props.gameData.line ? 1 : 0.5,
															transition: "all .4s ease-in-out",
															display: "flex",
															alignItems: "center",
															justifyContent: "center",
															minHeight: "fit-content",
														}}
													>
														<div
															style={{
																width: 70,
																background:
																	"var(--color_background_buttons_dark)",
																height: 45,
																borderRadius: 12,
																display: "flex",
																justifyContent: "center",
																flexDirection: "column",
																paddingLeft: 7,
																marginTop: 2,
															}}
														>
															<div
																style={{
																	fontWeight: 300,
																	fontSize: 12,
																}}
															>
																{i + 1} LVL
															</div>
															<div
																style={{
																	fontWeight: 500,
																	fontSize: 16,
																}}
															>
																x{bea_format(getCoefs(props.getBombs)[i])}
															</div>
														</div>
														<div
															style={{
																flexGrow: 1,
																display: "flex",
															}}
														>
															<Buttons props={props} item={i} />
														</div>
													</div>
												);
											})}
										</div>
									</div>
									<FormStatus
										mode={props.gameData.win === 0 ? "error" : "default"}
										header={
											props.gameData.win === 0 ? "Вы проиграли" : "Ваш выигрыш"
										}
										style={{
											marginTop: 10,
											borderRadius: "var(--radius_button)",
											background:
												props.gameData.win === 0
													? "rgba(244, 67, 54, .2)"
													: props.gameData.state === 3
													? "#009688"
													: "var(--color_background_buttons)",
										}}
									>
										<div
											style={{
												display: "flex",
												justifyContent: "flex-start",
												alignItems: "center",
												color:
													props.gameData.win === 0
														? "rgba(244, 67, 54, .6)"
														: "white",
												fontSize: 15,
											}}
										>
											{props.number_format(
												props.gameData.win === 0
													? props.gameData.bet
													: props.gameData.win
											)}
											<Icon28CoinsOutline
												width={17}
												height={17}
												style={{
													display: "inline-flex",
												}}
											/>
											<span
												style={{
													marginLeft: 4,
													color:
														props.gameData.win === 0
															? "rgba(244, 67, 54, .6)"
															: "white",
												}}
											>
												(x
												{bea_format(
													getCoefs(props.getBombs)[
														props.gameData.open.filter((x) => x !== -1).length -
															1
													]
												)}
												)
											</span>
										</div>
									</FormStatus>
									{props.gameData.state === 2 &&
										props.gameData.open.filter((x) => x !== -1).length > 0 && (
											<div
												onClick={() => props.get()}
												className="button"
												style={{
													marginTop: 10,
													borderRadius: "var(--radius_button)",
													border: "1px sloid graytext",
													fontSize: 17,
													fontWeight: 500,
													padding: 11,
													display: "flex",
													justifyContent: "center",
													width: "calc(100% - 22px)",
													background: "#e64646",
												}}
											>
												<Icon28CoinsOutline
													width={24}
													height={24}
													style={{
														marginRight: 8,
													}}
												/>
												Забрать выигрыш
											</div>
										)}
									{props.gameData.state === 3 && (
										<div
											onClick={() => props.continue()}
											className="button"
											style={{
												marginTop: 10,
												borderRadius: "var(--radius_button)",
												border: "1px sloid graytext",
												fontSize: 17,
												fontWeight: 500,
												padding: 11,
												display: "flex",
												justifyContent: "center",
												width: "calc(100% - 22px)",
												background: "#4986cc",
											}}
										>
											<Icon24DoneOutline
												width={24}
												height={24}
												style={{
													marginRight: 8,
												}}
											/>
											Продолжить
										</div>
									)}
									{props.gameData.state <= 2 && (
										<Footer style={{ marginTop: 5, color: "GrayText" }}>
											Hash: {props.gameData.hash}
										</Footer>
									)}
									{props.gameData.state === 3 && (
										<Fragment>
											<Footer
												style={{ margin: 0, marginTop: 5, color: "GrayText" }}
											>
												Hash: {props.gameData.hash}
											</Footer>
											<Footer style={{ marginTop: 5, color: "GrayText" }}>
												Md5: {props.gameData.md5}
											</Footer>
										</Fragment>
									)}
								</div>
							</Fragment>
						)}
					</div>
				</div>
			)}
		</Panel>
	);
};
const getCoefs = (t) => {
	if (t === 1) {
		return [1.12, 1.4, 1.75, 2.19, 2.74, 3.43, 4.29, 5.36, 6.7, 8.38];
	} else if (t === 2) {
		return [1.5, 2.5, 4.16, 6.94, 11.57, 19.29, 32.15, 53.58, 89.3, 148.84];
	} else if (t === 3) {
		return [
			2.25, 5.62, 14.06, 35.15, 87.89, 219.72, 549.31, 1373.29, 3433.22,
			8583.06,
		];
	} else if (t === 4) {
		return [
			4.5, 22.5, 112.5, 562.5, 2812.5, 14062.5, 70312.5, 351562.5, 1757812.5,
			8789062.5,
		];
	}
};
const bea_format = (v) => {
	if (v >= 1000 && v < 1000000) {
		return `${(Math.floor(v / 10) / 100).toFixed(2)}${"K".repeat(1)}`;
	} else if (v >= 1000000 && v < 1000000000) {
		return `${(Math.floor(v / 10000) / 100).toFixed(2)}${"K".repeat(2)}`;
	} else if (v >= 1000000000 && v < 1000000000000) {
		return `${(Math.floor(v / 10000000) / 100).toFixed(2)}${"K".repeat(3)}`;
	} else if (v >= 1000000000000 && v < 1000000000000000) {
		return `${(Math.floor(v / 10000000000) / 100).toFixed(2)}${"K".repeat(4)}`;
	} else if (v >= 1000000000000000 && v < 1000000000000000000) {
		return `${(Math.floor(v / 10000000000000) / 100).toFixed(2)}${"K".repeat(
			5
		)}`;
	} else {
		return v;
	}
};
export default Tower;
